def tracks_from(a,color):
 byu={}
 for r,row in enumerate(a):
  for c,v in enumerate(row):
   if v==color: byu.setdefault(r+c,[]).append(r)
 # split row sets into contig runs
 out=[]
 for u,rs in byu.items():
  rs=sorted(set(rs));runs=[]
  for r in rs:
   if not runs or r>runs[-1][-1]+1:runs.append([r])
   else:runs[-1].append(r)
  for run in runs:
   dvals=[2*r-u for r in run]
   out.append((u,min(run),max(run),min(dvals),max(dvals)))
 return sorted(out)
