def pair_region(t1,t2,R=16,C=16):
 u1,a1,b1,d1lo,d1hi=t1;u2,a2,b2,d2lo,d2hi=t2
 lo=max(d1lo,d2lo);hi=min(d1hi,d2hi)
 if u1>u2: u1,u2=u2,u1
 if lo>hi:return set()
 return {(r,c) for r in range(R) for c in range(C) if u1<r+c<u2 and lo<=r-c<=hi}
def eval_pairs(a,o,col):
